WITH candidates AS (
    SELECT id
    FROM sys_outbox
    WHERE published_at IS NOT NULL AND published_at < #{cutoff}
    ORDER BY published_at, id
    LIMIT #{limit}
    FOR UPDATE SKIP LOCKED
)
DELETE FROM sys_outbox o USING candidates c WHERE o.id = c.id

mapper.update:
UPDATE sys_outbox AS outbox SET published_at = CASE WHEN result.published THEN CURRENT_TIMESTAMP ELSE outbox.published_at END, attempts = CASE WHEN result.published THEN outbox.attempts ELSE outbox.attempts + 1 END, next_attempt_at = CASE WHEN result.published THEN outbox.next_attempt_at ELSE CURRENT_TIMESTAMP + LEAST(300, POWER(2, LEAST(outbox.attempts, 9))) * INTERVAL '1 second' END, failed_at = CASE WHEN result.published OR outbox.attempts + 1 < 10 THEN outbox.failed_at ELSE CURRENT_TIMESTAMP END FROM (VALUES
(#{result.eventId,jdbcType=OTHER}::uuid, #{result.published})
) AS result(id, published) WHERE outbox.id = result.id AND outbox.published_at IS NULL AND outbox.failed_at IS NULL
